"""In-memory durable store, cache layer, and base62 ID generator."""
import threading
from dataclasses import dataclass
from typing import Optional

_ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"


def encode_base62(num: int) -> str:
    if num == 0:
        return _ALPHABET[0]
    digits = []
    base = len(_ALPHABET)
    while num:
        num, rem = divmod(num, base)
        digits.append(_ALPHABET[rem])
    return "".join(reversed(digits))


@dataclass
class UrlMapping:
    short_code: str
    long_url: str
    created_at: str
    updated_at: str
    expires_at: Optional[str] = None
    owner_id: Optional[str] = None
    is_active: bool = True
    custom_alias: bool = False
    click_count_cache: int = 0


class IdGenerator:
    """Snowflake-like sequential id generator, base62 encoded."""

    def __init__(self, start: int = 1000):
        self._counter = start
        self._lock = threading.Lock()

    def next_code(self) -> str:
        with self._lock:
            self._counter += 1
            n = self._counter
        return encode_base62(n)


class MemoryStore:
    """Durable (in-process) key-value store standing in for a sharded DB."""

    def __init__(self):
        self._data = {}
        self._lock = threading.RLock()

    def put(self, mapping: UrlMapping):
        with self._lock:
            self._data[mapping.short_code] = mapping

    def get(self, code: str):
        with self._lock:
            return self._data.get(code)

    def delete(self, code: str) -> bool:
        with self._lock:
            return self._data.pop(code, None) is not None


class Cache:
    """Read-through / write-through cache in front of the MemoryStore."""

    def __init__(self, store: MemoryStore):
        self.store = store
        self._cache = {}
        self._lock = threading.RLock()

    def get(self, code: str):
        with self._lock:
            if code in self._cache:
                return self._cache[code]
        mapping = self.store.get(code)
        if mapping is not None:
            with self._lock:
                self._cache[code] = mapping
        return mapping

    def put(self, code: str, mapping: UrlMapping):
        self.store.put(mapping)
        with self._lock:
            self._cache[code] = mapping

    def invalidate(self, code: str):
        with self._lock:
            self._cache.pop(code, None)

"""Business logic tying storage, cache, id generation, and analytics."""
import threading
import uuid
from datetime import datetime, timezone

from .storage import MemoryStore, Cache, IdGenerator, UrlMapping
from .analytics import AnalyticsQueue, AnalyticsProcessor, ClickEvent


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


class URLService:
    """Stateless facade used by the API/redirect tier."""

    def __init__(self):
        self.store = MemoryStore()
        self.cache = Cache(self.store)
        self.idgen = IdGenerator()
        self.queue = AnalyticsQueue()
        self.processor = AnalyticsProcessor(self.queue)
        self._lock = threading.Lock()

    def create_url(self, long_url, custom_alias=None, expires_at=None, owner_id=None):
        code = custom_alias if custom_alias else self.idgen.next_code()
        if custom_alias and self.cache.get(code):
            raise ValueError("alias already taken")
        now = _now()
        mapping = UrlMapping(
            short_code=code, long_url=long_url, created_at=now, updated_at=now,
            expires_at=expires_at, owner_id=owner_id, is_active=True,
            custom_alias=bool(custom_alias),
        )
        self.cache.put(code, mapping)
        return mapping

    def get_url(self, code):
        return self.cache.get(code)

    def update_url(self, code, long_url=None, is_active=None):
        mapping = self.cache.get(code)
        if not mapping:
            return None
        if long_url is not None:
            mapping.long_url = long_url
        if is_active is not None:
            mapping.is_active = is_active
        mapping.updated_at = _now()
        self.cache.put(code, mapping)
        return mapping

    def delete_url(self, code):
        mapping = self.cache.get(code)
        if not mapping:
            return False
        self.store.delete(code)
        self.cache.invalidate(code)
        return True

    def redirect(self, code, ip="0.0.0.0", user_agent="", referrer="", country="unknown"):
        mapping = self.cache.get(code)
        if not mapping or not mapping.is_active:
            return None
        with self._lock:
            mapping.click_count_cache += 1
        event = ClickEvent(
            event_id=str(uuid.uuid4()), short_code=code, timestamp=_now(),
            ip_hash=str(hash(ip)), user_agent=user_agent, referrer=referrer,
            country=country, device_type="mobile" if "Mobile" in user_agent else "desktop",
            is_bot="bot" in user_agent.lower(),
        )
        self.queue.push(event)
        return mapping.long_url

    def get_analytics(self, code):
        mapping = self.cache.get(code)
        if not mapping:
            return None
        result = self.processor.get_analytics(code)
        result["total_clicks"] = max(result["total_clicks"], mapping.click_count_cache)
        return result

    def health(self):
        return {"status": "ok", "cache": "ok", "db": "ok", "queue": "ok"}

"""WSGI HTTP API for the URL shortener: create/read/update/delete + redirect."""
import json
import re
from urllib.parse import urlparse
from wsgiref.simple_server import make_server

from .service import URLService

service = URLService()

_SHORT_URL_RE = re.compile(r"^/api/v1/urls/([^/]+)$")
_ANALYTICS_RE = re.compile(r"^/api/v1/urls/([^/]+)/analytics$")


def _json_response(start_response, status, payload):
    body = json.dumps(payload).encode("utf-8")
    headers = [("Content-Type", "application/json"), ("Content-Length", str(len(body)))]
    start_response(status, headers)
    return [body]


def _read_json(environ):
    try:
        length = int(environ.get("CONTENT_LENGTH") or 0)
    except ValueError:
        length = 0
    if length <= 0:
        return {}
    raw = environ["wsgi.input"].read(length)
    return json.loads(raw or b"{}")


def _mapping_dict(m):
    return {
        "short_code": m.short_code, "long_url": m.long_url, "created_at": m.created_at,
        "updated_at": m.updated_at, "expires_at": m.expires_at, "is_active": m.is_active,
        "click_count": m.click_count_cache,
    }


def app(environ, start_response):
    method = environ["REQUEST_METHOD"]
    path = urlparse(environ.get("PATH_INFO", "")).path

    if method == "GET" and path == "/api/v1/health":
        return _json_response(start_response, "200 OK", service.health())

    if method == "POST" and path == "/api/v1/urls":
        data = _read_json(environ)
        long_url = data.get("long_url")
        if not long_url:
            return _json_response(start_response, "400 Bad Request", {"error": "long_url required"})
        try:
            mapping = service.create_url(
                long_url, custom_alias=data.get("custom_alias"), expires_at=data.get("expires_at")
            )
        except ValueError as e:
            return _json_response(start_response, "409 Conflict", {"error": str(e)})
        resp = {
            "short_code": mapping.short_code,
            "short_url": f"http://localhost/{mapping.short_code}",
            "long_url": mapping.long_url, "created_at": mapping.created_at,
            "expires_at": mapping.expires_at,
        }
        return _json_response(start_response, "201 Created", resp)

    m = _ANALYTICS_RE.match(path)
    if method == "GET" and m:
        code = m.group(1)
        result = service.get_analytics(code)
        if result is None:
            return _json_response(start_response, "404 Not Found", {"error": "not found"})
        return _json_response(start_response, "200 OK", result)

    m = _SHORT_URL_RE.match(path)
    if m:
        code = m.group(1)
        if method == "GET":
            mapping = service.get_url(code)
            if not mapping:
                return _json_response(start_response, "404 Not Found", {"error": "not found"})
            return _json_response(start_response, "200 OK", _mapping_dict(mapping))
        if method == "PUT":
            data = _read_json(environ)
            mapping = service.update_url(
                code, long_url=data.get("long_url"), is_active=data.get("is_active")
            )
            if not mapping:
                return _json_response(start_response, "404 Not Found", {"error": "not found"})
            return _json_response(start_response, "200 OK", {
                "short_code": mapping.short_code, "long_url": mapping.long_url,
                "updated_at": mapping.updated_at, "is_active": mapping.is_active,
            })
        if method == "DELETE":
            ok = service.delete_url(code)
            if not ok:
                return _json_response(start_response, "404 Not Found", {"error": "not found"})
            return _json_response(start_response, "200 OK", {"short_code": code, "deleted": True})

    if method == "GET" and path.startswith("/") and path.count("/") == 1 and not path.startswith("/api"):
        code = path[1:]
        long_url = service.redirect(
            code, ip=environ.get("REMOTE_ADDR", "0.0.0.0"),
            user_agent=environ.get("HTTP_USER_AGENT", ""),
            referrer=environ.get("HTTP_REFERER", ""),
        )
        if not long_url:
            return _json_response(start_response, "404 Not Found", {"error": "not found"})
        start_response("302 Found", [("Location", long_url), ("Content-Length", "0")])
        return [b""]

    return _json_response(start_response, "404 Not Found", {"error": "not found"})


def main():
    with make_server("", 8000, app) as httpd:
        httpd.serve_forever()


if __name__ == "__main__":
    main()
